 <?php $__env->startSection('title','Бронирование'); ?> <?php $__env->startSection('content'); ?><section class="dashboard-wrap"><div class="container narrow"><div class="eyebrow">BOOK YOUR SESSION</div><h1>ЗАБРОНИРУЙ <span>СТАРТ.</span></h1><p class="muted mb-4">Заполни данные. Заявка поступит сотруднику на подтверждение.</p><div class="panel"><form method="POST" action="<?php echo e(route('booking.store')); ?>"><?php echo csrf_field(); ?><div class="mb-4"><label class="form-label">Тариф</label><select class="form-select" name="tariff_id" required><option value="">Выбери тариф</option><?php $__currentLoopData = $tariffs; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $tariff): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($tariff->id); ?>" <?php if(old('tariff_id')==$tariff->id): echo 'selected'; endif; ?>><?php echo e($tariff->name); ?> — <?php echo e(number_format($tariff->price,0,',',' ')); ?> ₽ / <?php echo e($tariff->duration); ?> мин.</option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="mb-4"><label class="form-label">Дата и время</label><input class="form-control" type="datetime-local" name="start_at" min="<?php echo e(now()->addHour()->format('Y-m-d\TH:i')); ?>" value="<?php echo e(old('start_at')); ?>" required></div><div class="mb-3"><label class="form-label">Участники</label><div id="participants"><div class="participant-input mb-2"><input class="form-control" name="participants[]" placeholder="Имя участника 1" required></div></div><button class="btn btn-outline-light btn-sm" type="button" id="addParticipant">+ Добавить участника</button><div class="form-text">До 8 участников в одной заявке.</div></div><div class="mb-4 mt-3"><label class="form-label">Комментарий (необязательно)</label><textarea class="form-control" name="comment" rows="3" placeholder="Пожелания к бронированию"><?php echo e(old('comment')); ?></textarea></div><button class="btn btn-accent btn-lg w-100">Отправить заявку ↗</button></form></div></div></section><?php $__env->stopSection(); ?>

